# -*- coding: utf-8 -*-
T=[]
# ---------- Day 2 A: word order ----------
T.append(dict(id="g-wo",sec="writing",day=2,task="English word order",before="Clinic 1 · English word order: choose",
 emoji="🚦",kicker="TRAFFIC CONTROL · WORD ORDER",title="The Wandering<br>Adverb",ch1="The traffic jam",
 hook="Welcome, traffic controller. Words in English drive in fixed lanes. But one little word keeps wandering into the wrong lane and causing a jam. Today you will send every word to its correct place.",
 A="She checks <b>usually</b> her email.",B="She <b>usually checks</b> her email.",
 cmp="Look at these two sentences. Version A: she checks usually her email. Version B: she usually checks her email. Same words, almost the same meaning. But one of them is a traffic accident.",
 verdict="Version A crashed. The adverb usually is standing between the verb and its object. In version B, usually moves before the verb and the traffic flows. One word in the wrong lane, and the whole sentence feels wrong.",
 whyHead="Every Build a Sentence item",whySub="Word order is the skeleton of every sentence",why="Why does this matter? In Build a Sentence you place words in order, over and over. If you know the lanes, you can build almost any sentence quickly, and with confidence.",
 rule=[
  dict(legend=["s:subject","v:verb","n:object","q:place / time"],sub="The main road",rows=["s:She|v:drinks|n:coffee|q:in the morning"],say="This is the main road. First the subject, then the verb, then the object, then place and time. Subject, verb, object, place, time. Almost every English sentence follows this road."),
  dict(sub="Frequency adverbs: before the main verb",rows=["s:She|q:usually|v:checks|n:her email"],pair=None,note="always · usually · often · sometimes · never",say="Frequency adverbs like always, usually, often and never go before the main verb. She usually checks her email. They never stand between the verb and its object."),
  dict(sub="But after the verb be",rows=["s:He|v:is|q:always|n:late"],note="is · are · was · were → adverb comes AFTER",say="There is one exception. With the verb be, the adverb comes after it. He is always late. Remember: before most verbs, but after be."),
  dict(sub="Adjective order: opinion, size, age, color, material",rows=["n:a|q:lovely|q:big|q:old|q:brown|q:wooden|n:table"],note="Say it as a song: opinion · size · age · color · material",say="Adjectives also have a fixed order: opinion, size, age, color, material. A lovely big old brown wooden table. If you change the order, the phrase sounds strange to an English ear."),
  dict(sub="Phrasal verbs with a pronoun",pair=["✗ wrong","She picked up it.","✓ right","She picked <b>it</b> up."],say="One more lane rule. With a phrasal verb and a pronoun, the pronoun goes in the middle. She picked it up, not she picked up it. With a noun, both work: picked up the phone, or picked the phone up.")],
 trap=dict(es="Ella revisa <b>siempre</b> su correo. · una mesa <b>grande</b>",esnote="adverbs move freely · adjectives after the noun",say1="Now, the trap. In Spanish, adverbs can move freely: ella revisa siempre su correo. And the adjective follows the noun: una mesa grande. Both are perfectly correct in Spanish.",
  es2="ella revisa <b>siempre</b> su correo",enbad="she checks <b>always</b> her email",say2="But when Spanish speakers copy that into English, they write: she checks always her email. It feels natural, but it is a traffic accident. Never put an adverb between the verb and its object.",
  stop="Do not copy the Spanish lanes",engood="She <b>always checks</b> her email. · a <b>big</b> table",say3="So, stop. English has fixed lanes. The adverb goes before the verb, and the adjective goes before the noun, in the correct order.",
  more=[["Trap 2 · adjective order ✗","a <b>wooden big</b> table","Fixed ✓","a <b>big wooden</b> table","🔄","The second trap is adjective order. Size comes before material. A big wooden table. If you are unsure, remember the song: opinion, size, age, color, material."],
        ["Trap 3 · enough ✗","The room is not <b>enough big</b>.","Fixed ✓","The room is not big <b>enough</b>.","🔄","The third trap is enough. With an adjective, enough comes after it. Big enough, not enough big. With a noun, it comes before: enough time."]]),
 quiz=["She ___ her homework.",["does always","always does","does her always"],1],
 quizsay="Quick quiz. She, blank, her homework. Where does always go? Think. ... The answer is B. She always does her homework. The adverb goes before the main verb.",
 fix=dict(sub="Fix the sentence",row="s:I|v:watched|g:yesterday|n:a film|q:yesterday",say="Now fix this one. I watched yesterday a film. Time words go at the end. So yesterday leaves its place and moves to the end: I watched a film yesterday."),
 recap=["Subject, verb, object, <b>place, time</b>","Frequency adverb <b>before the verb</b> (after be)","Adjectives: <b>opinion, size, age, color, material</b>"],
 recapsay="Three things to remember. One: subject, verb, object, place, time. Two: frequency adverbs go before the verb, but after be. Three: adjectives follow the order opinion, size, age, color, material.",
 done="Traffic is flowing!",donesay="The traffic is flowing again, controller. Well done. Now go to the practice: choose the correct one, find the error, correct and transform. Remember: subject, verb, object, place, time. Good luck!",
 check=dict(why1="Frequency adverbs go before the main verb.",q2="Choose the correct sentence.",a2="I watched a film yesterday.",w2=["I watched yesterday a film.","Yesterday I a film watched.","I yesterday watched a film."],why2="Object next to the verb, time at the end.")))
# ---------- Day 2 B: agreement ----------
T.append(dict(id="g-sva",sec="writing",day=2,task="Subject-verb agreement",replace="Clinic 2 · Subject-verb agreement: notice",
 emoji="🤝",kicker="THE HANDSHAKE · AGREEMENT",title="Subject and Verb<br>Must Shake Hands",ch1="The handshake",
 hook="Welcome to the handshake club. Every subject needs a verb partner, and they must shake hands correctly: singular with singular, plural with plural. Today you will learn to spot the wrong handshake.",
 A="The number of students <b>are</b> growing.",B="The number of students <b>is</b> growing.",
 cmp="Look at these two sentences. Version A: the number of students are growing. Version B: the number of students is growing. Which verb shakes hands with the subject?",
 verdict="Version B is correct. The subject is the number, which is singular. The word students sits next to the verb, but it is not the subject. A wrong handshake happens when we shake hands with the nearest word.",
 stampA="BAD HANDSHAKE",whyEmoji="⚠️",whyHead="A silent error raters notice",whySub="Agreement mistakes appear in almost every writing sample",why="Why does this matter? Agreement errors are small, but they are everywhere. Raters see them quickly, and they lower your accuracy score. A strong handshake makes your writing look careful.",
 rule=[
  dict(legend=["s:subject","v:verb","n:distractor"],sub="Find the head of the subject",rows=["n:The","s:number|n:of students|v:is|n:growing"],say="First, find the head of the subject. In the number of students, the head is number. The words of students are only extra information. The verb agrees with the head: the number is growing."),
  dict(sub="A number of = many",rows=["n:A|s:number|n:of students|v:are|n:absent"],note="The number of → singular · A number of → plural",say="But a number of means many. A number of students are absent. The number of is singular. A number of is plural. Small word, big difference."),
  dict(sub="Each, every, everyone: singular",rows=["s:Each|n:of the students|v:has|n:a laptop"],note="each · every · everyone · somebody → has / is",say="Words like each, every and everyone are always singular. Each of the students has a laptop. Everyone is ready. Even if the meaning feels like many people."),
  dict(sub="Uncountable nouns: singular",rows=["s:The news|v:is|n:good"],note="news · information · advice · mathematics",say="Uncountable nouns take a singular verb too. The news is good. The information is useful. Mathematics is my favorite subject. And remember: information has no plural."),
  dict(sub="Plural words that look singular",rows=["s:People|v:are|n:waiting"],note="people · police · staff (team) → plural",say="Finally, some plural words do not end in s. People are waiting. The police are here. Check these carefully, because they do not look plural.")],
 trap=dict(es="La gente <b>espera</b>. · La información <b>es</b> útil.",esnote="gente is singular in Spanish",say1="Now, the trap. In Spanish, the word gente, people, is singular: la gente espera. So Spanish speakers want to write: the people waits. But English treats people as plural.",
  es2="la gente <b>espera</b>",enbad="the people <b>waits</b>",say2="So they write: the people waits. Or: the informations are useful. Both are wrong. The first needs a plural verb. The second uses an uncountable noun as plural.",
  stop="Check the head and the type",engood="The people <b>wait</b>. The information <b>is</b> useful.",say3="So, stop. Ask two questions: what is the head of the subject, and is the noun singular, plural, or uncountable? Then choose the verb.",
  more=[["Trap 2 · the nearest word ✗","The list of items <b>are</b> long.","Fixed ✓","The list of items <b>is</b> long.","🔎","The second trap is the nearest word. Items is plural and sits next to the verb. But the head is list. The list is long."]]),
 quiz=["Everyone in the class ___ ready.",["are","is","be"],1],
 quizsay="Quick quiz. Everyone in the class, blank, ready. Think about the head. ... The answer is B. Everyone is ready. Everyone is always singular.",
 fix=dict(sub="Fix the handshake",row="n:The information|g:are|v:is|n:useful",say="Fix this one. The information are useful. Information is uncountable, so the verb must be singular. The information is useful."),
 recap=["Find the <b>head</b> of the subject","<b>The number of</b> = is · <b>a number of</b> = are","<b>Each, everyone, news, information</b> = singular"],
 recapsay="Three things to remember. One, find the head of the subject. Two, the number of is singular, and a number of is plural. Three, each, everyone, news and information take a singular verb.",
 done="Perfect handshake!",donesay="Perfect handshake! You can now spot the wrong partner in a sentence. Go to the practice and remember: find the head, then choose the verb. Good luck!",
 check=dict(why1="Everyone is always singular.",q2="Choose the correct sentence.",a2="The number of students is growing.",w2=["The number of students are growing.","The number of student are growing.","The number of students were growing."],why2="The head of the subject is number, which is singular.")))
# ---------- Day 3 A: questions ----------
T.append(dict(id="g-q",sec="writing",day=3,task="Question forms",before="Clinic 1 · Question forms: choose",
 emoji="🏭",kicker="THE QUESTION FACTORY",title="Build a Question<br>in Four Parts",ch1="The factory",
 hook="Welcome to the Question Factory. Every English question is built on a short assembly line with four parts. Today you will learn the line, and your questions will come out perfect every time.",
 A="Where <b>she works</b>?",B="Where <b>does she work</b>?",
 cmp="Look at these two questions. Version A: where she works. Version B: where does she work. Both use the same words, but one question left the factory without a part.",
 verdict="Version A is missing the helper verb. In English, most questions need does, do or did. Version B has all the parts. Do you see how the s on works moved to does?",
 stampA="MISSING PART",whyHead="Questions are everywhere",whySub="Emails · Build a Sentence · speaking · listening",why="Why does this matter? Questions appear in Build a Sentence, in emails to professors, and in everyday talk. If your question is accurate, the reader trusts you from the first line.",
 rule=[
  dict(legend=["q:question word","aux:helper","s:subject","v:base verb"],sub="The assembly line",rows=["q:Where|aux:does|s:she|v:work|n:?"],say="Here is the assembly line. Part one, the question word. Part two, the helper verb. Part three, the subject. Part four, the base verb. Where does she work?"),
  dict(sub="The helper decides the ending",rows=["q:What time|aux:does|s:the class|v:start"],note="does + base verb · the s moves to does",say="Notice that the s ending moves to the helper. She works becomes does she work. The main verb goes back to its base form. What time does the class start?"),
  dict(sub="With be and modals: no helper needed",rows=["q:Where|aux:are|s:they|v:going"],note="is · are · was · were · can · will + subject",say="With the verb be, or with modals like can and will, you do not need do or does. The verb itself jumps in front of the subject. Where are they going? What can you see?"),
  dict(sub="Subject questions: no helper at all",pair=["Direct (object)","Who <b>did</b> you call?","Subject question","Who <b>called</b> you?"],say="One special case. When the question word is the subject, there is no helper. Who called you? Who broke the window? The question word stands in the place of the subject."),
  dict(sub="Negative questions",rows=["q:Why|aux:doesn't|s:he|v:like|n:coffee|n:?"],note="Why + doesn't + subject + base verb",say="Negative questions follow the same line. Why doesn't he like coffee? Put the negative helper after the question word, then the subject, then the base verb.")],
 trap=dict(es="¿Dónde <b>trabaja</b> ella? · ¿Qué <b>significa</b> esta palabra?",esnote="no helper needed in Spanish",say1="Now the trap. Spanish questions need no helper. You just change your voice: dónde trabaja ella. Or: qué significa esta palabra. There is no word like does.",
  es2="¿qué <b>significa</b> esta palabra?",enbad="what <b>means</b> this word?",say2="So Spanish speakers copy the same shape into English: what means this word. English readers expect the helper. A question without it sounds broken.",
  stop="Never forget the helper",engood="What <b>does</b> this word <b>mean</b>?",say3="So, stop. In English, put the helper after the question word, then the subject, then the base verb. What does this word mean?",
  more=[["Trap 2 · the extra s ✗","Where does she <b>works</b>?","Fixed ✓","Where does she <b>work</b>?","✂️","The second trap is the extra s. After does, the verb goes back to its base form. Where does she work, not works. Only one verb carries the ending."],
        ["Trap 3 · How many ✗","How many students <b>is</b> there?","Fixed ✓","How many students <b>are</b> there?","🔧","The third trap is how many with a plural noun. The verb must agree: how many students are there. How much information is there, because information is uncountable."]]),
 quiz=["___ she work in the library?",["Do","Does","Is"],1],
 quizsay="Quick quiz. Blank she work in the library. Which helper goes with she? Think. ... The answer is B. Does she work in the library? Does goes with he, she and it.",
 fix=dict(sub="Fix the question",row="q:What|g:means|aux:does|s:this word|v:mean|n:?",say="Fix this one. What means this word. Add the helper does, and put the verb in its base form. What does this word mean?"),
 recap=["<b>Question word</b> + <b>helper</b>","Then the <b>subject</b>, then the <b>base verb</b>","If the question word is the subject: <b>no helper</b>"],
 recapsay="Three things to remember. One, question word and helper. Two, then the subject, then the base verb. Three, if the question word is the subject, there is no helper.",
 done="Question factory open!",donesay="The factory is open, and your questions are perfect. Now go to the practice. Remember the line: question word, helper, subject, base verb. Good luck!",
 check=dict(why1="Does goes with he, she and it.",q2="Choose the correct question.",a2="What time does the class start?",w2=["What time the class starts?","What time does the class starts?","What time starts the class?"],why2="Question word + helper + subject + base verb.")))
# ---------- Day 3 B: tenses ----------
T.append(dict(id="g-ten",sec="writing",day=3,task="Present perfect and past simple",replace="Clinic 2 · Tenses: present perfect and past simple: notice",
 emoji="⏳",kicker="THE TIME MACHINE",title="Past Simple or<br>Present Perfect?",ch1="Set the clock",
 hook="Welcome to the time machine. Two English tenses talk about the past, but they travel differently. One stays in the past. The other keeps one foot in the present. Today you will learn which to choose.",
 A="I <b>have visited</b> Sucre in 2019.",B="I <b>visited</b> Sucre in 2019.",
 cmp="Look at these two sentences. Version A: I have visited Sucre in 2019. Version B: I visited Sucre in 2019. Both talk about the past. Which one fits the time machine?",
 verdict="Version B is correct. The year 2019 is a finished time, so the past simple stays in the past. Version A uses the present perfect, which connects to now, and it cannot be used with a finished date.",
 stampA="WRONG ERA",whyHead="Tenses build your credibility",whySub="Examples, experience, trends: all need the right tense",why="Why does this matter? In emails and discussion posts you give examples from the past all the time. The right tense shows the reader exactly when things happened and how they connect to now.",
 rule=[
  dict(legend=["s:finished time","v:connected to now"],sub="Two clocks",rows=["s:yesterday · last year · in 2019|v:since · for · so far · recently"],say="Think of two clocks. The first clock shows finished time: yesterday, last year, in 2019. The second clock shows time connected to now: since, for, so far, recently."),
  dict(sub="Past simple = finished",rows=["s:I|v:visited|n:Sucre|q:in 2019"],note="finished time → past simple",say="With a finished time, use the past simple. I visited Sucre in 2019. Last year the city built a park. The action is closed in the past."),
  dict(sub="Present perfect = connected to now",rows=["s:I|aux:have|v:lived|n:here|q:since 2018"],note="have / has + past participle",say="With time that reaches now, use the present perfect. I have lived here since 2018. The city has changed a lot. Have or has, plus the past participle."),
  dict(sub="Since and for",pair=["since + point in time","I have worked here <b>since March</b>.","for + length of time","I have worked here <b>for six months</b>."],say="Two small words help. Since goes with a starting point: since March, since 2018. For goes with a length: for six months, for three years. Both use the present perfect."),
  dict(sub="Experience: ever, never, already",rows=["s:Have|s:you|v:ever|v:visited|n:Tarija|n:?"],note="no finished time mentioned",say="Use the present perfect for experience when no finished time is given. Have you ever visited Tarija? I have never tried sushi. But as soon as you give a finished time, go back to the past simple.")],
 trap=dict(es="Vivo aquí <b>desde</b> 2018. · Este año <b>he viajado</b>.",esnote="Spanish uses present and perfect differently",say1="Now, the trap. In Spanish, you say: vivo aquí desde 2018, using the present. And Spanish often uses the perfect for finished times: este año he viajado a Sucre.",
  es2="vivo aquí desde 2018",enbad="I <b>live</b> here since 2018",say2="So Spanish speakers write: I live here since 2018. In English, a situation that started in the past and continues needs the present perfect. I have lived here since 2018.",
  stop="Since means present perfect",engood="I <b>have lived</b> here since 2018.",say3="So, stop. When you see since or for with a situation that is still true, choose the present perfect. And never use the present perfect with a finished date.",
  more=[["Trap 2 · finished date ✗","Last year the council <b>has built</b> a park.","Fixed ✓","Last year the council <b>built</b> a park.","⏪","The second trap is a finished date. Last year, yesterday and in 2019 close the time. Use the past simple: the council built a park."]]),
 quiz=["I ___ in Santa Cruz since 2018.",["live","have lived","lived"],1],
 quizsay="Quick quiz. I, blank, in Santa Cruz since 2018. Which tense? Think. ... The answer is B. I have lived in Santa Cruz since 2018. Since needs the present perfect.",
 fix=dict(sub="Fix the sentence",row="s:Prices|g:rose|aux:have|v:risen|n:since 2020",say="Fix this one. Prices rose since 2020. Since reaches now, so use the present perfect: prices have risen since 2020."),
 recap=["<b>Finished time</b> (yesterday, in 2019) → past simple","<b>Since / for</b> + still true → present perfect","<b>Never put</b> a finished date with the present perfect"],
 recapsay="Three things to remember. One, a finished time needs the past simple. Two, since or for with something still true needs the present perfect. Three, never use the present perfect with a finished date.",
 done="Time machine ready!",donesay="The time machine is ready. Now go to the practice and remember: finished time means past simple, since or for means present perfect. Good luck, traveler!",
 check=dict(why1="Since needs the present perfect.",q2="Choose the correct sentence.",a2="I visited Sucre in 2019.",w2=["I have visited Sucre in 2019.","I visit Sucre in 2019.","I am visiting Sucre in 2019."],why2="A finished date needs the past simple.")))
